"""SWM operations"""

import re
import time
from taf.ul.trs_e2e_fw.lib.ems.exceptions import FailedToImportBuild, FailedToDownloadBuild
from taf.ul.trs_e2e_fw.lib.ems.nom.nom_base import NomBase
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.build_download.build_download import BuildDownload
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class SWMOperations(NomBase):

    def __init__(self):
        super(SWMOperations, self).__init__()
        self.build_download = BuildDownload()

    def software_manage(self, **kwargs):
        """Software manage"""
        operation = kwargs['operation']
        return getattr(self, '_{}'.format(operation.lower()))(**kwargs)

    def _provision(self, **kwargs):

        package_name = kwargs['package']
        version_number = kwargs.get('version_number', None)
        timeout = kwargs.get('timeout', 1200)

        provision_param = get_config_variable(["sw_provision", kwargs.get("provision_param", "provision")])
        dist_name = [provision_param.get("dist_name", self.bts_moc_id)]
        run_async = provision_param.get("run_async", False)
        precheck = provision_param.get("precheck", None)
        postcheck = provision_param.get("postcheck", None)

        version_id = latest_buildnum = None

        if package_name.lower() == 'auto':
            wft_profile = kwargs['wft_profile']
            download_url, latest_buildnum, package_template = self.build_download.find_latest_build(wft_profile)
            logger.debug("download url {} latest_buildnum {} package_template {}".format(
                download_url, latest_buildnum, package_template))
            package_name = self._download_and_import_build(package_name=package_name,
                                                           latest_buildnum=latest_buildnum,
                                                           build_download=True,
                                                           package_template=package_template,
                                                           download_url=download_url)
        else:
            if re.search(r'SBTS00\w\D*_9999', package_name) and version_number:
                version_id = package_name.replace("_release_BTSSM_downloadable_A54.zip", "").replace("SBTS00",
                                                                                                     version_number)
            else:
                version_id = package_name.replace("_release_BTSSM_downloadable_A54.zip", "")
            logger.debug("Version Id is {} \n package name is {}".format(version_id, package_name))
            package_name = self._download_and_import_build(
                package_name=package_name,
                latest_buildnum=version_id, build_download=False)
        logger.info("Package name to download is {}".format(version_id))
        logger.info("BTS moc id is {}".format(self.bts_moc_id))
        time.sleep(300)
        return self.nom_factory.nom.provision_sw(dist_name, latest_buildnum, download=False, activate=False,
                                                 timeout=timeout, run_async=run_async, provision=True,
                                                 precheck=precheck, postcheck=postcheck)

    def _download(self, **kwargs):

        package_name = kwargs['package']
        version_number = kwargs.get('version_number', None)
        timeout = kwargs.get('timeout', 1200)
        provision_param = get_config_variable(["sw_provision", kwargs.get("provision_param")])
        dist_name = [provision_param.get("dist_name", self.bts_moc_id)]
        run_async = provision_param.get("run_async", False)
        precheck = provision_param.get("precheck", None)
        postcheck = provision_param.get("postcheck", None)

        if package_name.lower() == 'auto':
            wft_profile = kwargs['wft_profile']
            download_url, latest_buildnum, package_template = self.build_download.find_latest_build(wft_profile)
            logger.debug("download url {} latest_buildnum {} package_template {}".format(
                download_url, latest_buildnum, package_template))
            package_name = self._download_and_import_build(package_name=package_name,
                                                           latest_buildnum=latest_buildnum,
                                                           build_download=True,
                                                           package_template=package_template,
                                                           download_url=download_url)
        else:
            if re.search(r'SBTS00\w\D*_9999', package_name) and version_number:
                version_id = package_name.replace("_release_BTSSM_downloadable_A54.zip", "").replace("SBTS00",
                                                                                                     version_number)
            else:
                version_id = package_name.replace("_release_BTSSM_downloadable_A54.zip", "")
            package_name = self._download_and_import_build(package_name=package_name,
                                                           latest_buildnum=version_id,
                                                           build_download=False)
        logger.info("Package name to download is {}".format(version_id))
        logger.info("BTS moc id is {}".format(self.bts_moc_id))
        return self._perform_swm_download(version_id, timeout, dist_name, precheck, postcheck, run_async)

    def _perform_swm_download(self, package_name, timeout, integrated_ids, precheck, postcheck, run_async):
        resp = None
        try:
            resp = self.nom_factory.nom.provision_sw(integrated_ids, package_name, download=True,
                                                     activate=False, timeout=timeout, run_async=run_async,
                                                     provision=False, precheck=precheck, postcheck=postcheck)

            logger.debug("*********************Response from swm_download {}".format(resp))
        except Exception as e:
            logger.debug("*************** swm download threw an exception: {0}. Attempting to retry the "
                         "operation".format(e))
            time.sleep(300)
            resp = self.nom_factory.nom.provision_sw(integrated_ids, package_name, download=True,
                                                     activate=False, timeout=timeout, run_async=run_async,
                                                     provision=False, precheck=precheck, postcheck=postcheck)
        finally:
            return resp

    def _download_and_import_build(self, package_name, latest_buildnum, build_download=True, **kwargs):
        ne_type = kwargs.get("ne_type", "MRBTS")
        max_try = 3
        is_imported = False
        build_list = self.nom_factory.nom.get_sw_package_list(ne_type=ne_type)
        build_list = [dictn["ne_sw_version"] for dictn in build_list]
        if latest_buildnum in build_list:
            is_imported = True
        logger.debug("#### Is imported {}".format(is_imported))
        if not is_imported:
            package, package_name = self._download_build(**kwargs) if build_download else \
                self._ret_build_info(package_name)
            try:
                logger.debug("Package_name is {}".format(package_name))
                logger.debug("Importing the builds")
                self.nom_factory.nom.import_sw_package(package_name, ne_type, ne_sw_version=latest_buildnum)
            except Exception as e:
                while max_try != 0:
                    logger.debug("Exception {} while importing {}".format(e, package_name))
                    logger.debug("Retrying to import {}".format(package_name))
                    self.nom_factory.nom.import_sw_package(package_name, ne_type, ne_sw_version=latest_buildnum)
                    time.sleep(2)
                    build_list = self.nom_factory.nom.get_sw_package_list(ne_type=ne_type)
                    build_list = [dictn["ne_sw_version"] for dictn in build_list]
                    if latest_buildnum in build_list:
                        is_imported = True

                    max_try -= 1
                    if is_imported:
                        break
                else:
                    raise FailedToImportBuild
            logger.debug("#### successfully im,ported build {}".format(package_name))
            return package_name
        logger.debug("Package {} is already imported".format(package_name))

    def _ret_build_info(self, package_name):
        return None, package_name

    def _download_build(self, **kwargs):
        latest_buildnum = kwargs["latest_buildnum"]
        download_url = kwargs["download_url"]
        package_template = kwargs["package_template"]
        download_path = kwargs.get("download_path", "execution_logs")
        try:
            package, package_name = self.build_download.download_latest_build(
                latest_buildnum, download_url, package_template, download_path)
            logger.info("Build download is successful")
            logger.info("Package is {} AND package_name is {}".format(package, package_name))
            return package, package_name
        except FailedToDownloadBuild as e:
            raise FailedToImportBuild("Failed to download build {}".format(e))
        except Exception as e:
            raise Exception("Caught exception from framework {}".format(e))

    def _activate(self, **kwargs):

        package_name = kwargs['package']
        version_number = kwargs.get('version_number', None)
        timeout = kwargs.get('timeout', 600)
        provision_param = get_config_variable(["sw_provision", kwargs.get("provision_param")])
        dist_name = [provision_param.get("dist_name", self.bts_moc_id)]
        run_async = provision_param.get("run_async", False)
        precheck = provision_param.get("precheck", None)
        postcheck = provision_param.get("postcheck", None)

        if re.search(r'SBTS00\w\D*_9999', package_name) and version_number:
            version_id = package_name.replace("_release_BTSSM_downloadable_A54.zip", "").replace("SBTS00",
                                                                                                 version_number)
        else:
            version_id = package_name.replace("_release_BTSSM_downloadable_A54.zip", "")
        return self.nom_factory.nom.provision_sw(dist_name, version_id, download=False, activate=True,
                                                 timeout=timeout, run_async=run_async, provision=False,
                                                 precheck=precheck, postcheck=postcheck)

    def rollback_sw(self, **kwargs):
        """
        *Keyword:* Rollback Software From Nom
        Execute rollback operation on given distnames.
        """
        dist_names = [kwargs["dist_names"]]
        timeout = kwargs.pop("timeout", 600)

        return self.nom_factory.nom.rollback_sw(integrated_ids=dist_names, timeout=timeout)
